export function categoryIconGroupsForType(type: LedgerType): readonly (typeof CATEGORY_ICON_GROUPS)[number][] {
  return CATEGORY_ICON_GROUPS.filter((group) => type === 'income' ? group.name === '收入' : group.name !== '收入')
}

export function defaultCategoryIcon(type: LedgerType): string {
  return type === 'income' ? 'cat_income' : 'cat_other'
}

