import type { Category } from '@/domain/models/category'

/** 全局兜底色（与 --color-primary 一致）。用于一级分类也没 color 的极端情况 */
const FALLBACK_COLOR = '#1677ff'
/** 软色背景的 alpha 值 */
const SOFT_ALPHA = 0.12

interface RgbColor { r: number; g: number; b: number }

/** 解析 hex 字符串（如 '#1677ff' / '#FFF'）到 RGB 元组 */
export function hexToRgb(hex: string): RgbColor {
  const trimmed = hex.trim().replace(/^#/, '')
  const normalized = trimmed.length === 3
    ? trimmed.split('').map((char) => char + char).join('')
    : trimmed
  if (!/^[0-9a-fA-F]{6}$/.test(normalized)) return { r: 22, g: 119, b: 255 }
  const value = Number.parseInt(normalized, 16)
  return { r: (value >> 16) & 0xff, g: (value >> 8) & 0xff, b: value & 0xff }
}

/**
 * 解析分类的有效颜色：
 * - 一级分类有自己的 color → 直接用
 * - 二级分类无 color → 回退到所属一级分类的 color
 * - 都没有 → 全局兜底
 */
export function colorOf(category: Category, all: readonly Category[]): string {
  if (category.color) return category.color
  if (category.parentId) {
    const parent = all.find((item) => item.id === category.parentId)
    if (parent?.color) return parent.color
  }
  return FALLBACK_COLOR
}

/** 派生 soft 背景色（同色 + 12% 透明度） */
export function softOf(hex: string): string {
  const { r, g, b } = hexToRgb(hex)
  return `rgba(${r}, ${g}, ${b}, ${SOFT_ALPHA})`
}